// THE OPERATOR HOLD (tasks-dispatch DESIGN §8, decision §15.24). One repository
// Actions variable stops the whole queue: every Claudinite workflow stamps it
// into its env, and every engine entry point checks it as its FIRST act — before
// any read, like the dormancy gate beside it — and exits cleanly having fired
// nothing.
//
// Why a variable rather than a commit: cancelling one run means "move on", an
// intent the failure continuation and the leash already serve. Stopping the
// SYSTEM is a different intent, and the only lever that existed for it was
// dormancy, which needs a commit and a converge to take effect and another to
// undo. A variable takes effect on the next run and clears the same way.
//
// What it freezes: STARTS, not running work. A run already past this gate
// finishes its item — killing live work would leave exactly the half-done state
// the leash exists to recover — so an in-flight run may close an item after the
// hold goes on. Nothing NEW is ever picked.
//
// Resume needs no code: clear the variable and the next tick reclaims, readies and
// drains on its own. The impatient path is dispatching the SCHEDULER workflow, not
// the bare executor — the tick is what re-derives the world.

export const SUSPEND_ALL_VAR = 'CLAUDINITE_TASKS_SUSPEND_ALL';

// Deliberately narrow: a variable somebody set to `false` or `0` to mean "off"
// must not read as on. Anything else — unset, empty, a word — is not a hold.
export const isSuspended = (env = process.env) =>
  ['true', '1', 'yes'].includes(String(env[SUSPEND_ALL_VAR] ?? '').trim().toLowerCase());

// The one line every entry point prints when it parks, so a run that did nothing
// says WHY it did nothing — a silent clean exit is indistinguishable from a run
// that found no work.
export const suspendedNotice = () =>
  `- ${SUSPEND_ALL_VAR} is set: the queue is held. Nothing is picked up, created, readied or reclaimed.\n`
  + '  Clear the variable in repo settings (Settings → Secrets and variables → Actions → Variables) to resume;'
  + ' the next scheduled tick recovers everything on its own.';

// The operator hold (DESIGN §8, §15.24) and the two bounds the heartbeat left
// behind. What is pinned here is the part that has bitten this repo before: a
// safety knob whose producer and consumer stopped agreeing, and a parameter that
// defaults to the operation's most dangerous mode when it stops being read.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { SUSPEND_ALL_VAR, isSuspended, suspendedNotice } from '../../../engine/scheduler/queue/suspend.mjs';
import { HEARTBEAT_MS } from '../../../engine/scheduler/queue/heartbeat.mjs';
import { EXECUTING_LEASH_MS } from '../../../engine/scheduler/queue/leases.mjs';

const CANON = join(dirname(fileURLToPath(import.meta.url)), '../../..');
const read = (p) => readFileSync(join(CANON, p), 'utf8');

test('the hold reads as on only for a deliberate yes', () => {
  for (const on of ['true', 'TRUE', ' true ', '1', 'yes']) {
    assert.equal(isSuspended({ [SUSPEND_ALL_VAR]: on }), true, on);
  }
  // A variable somebody set to `false` to mean "off" must never read as a hold —
  // and neither must the unset case, which is every repo that never touched it.
  for (const off of ['false', '0', 'no', '', undefined, 'maybe']) {
    assert.equal(isSuspended({ [SUSPEND_ALL_VAR]: off }), false, String(off));
  }
  assert.equal(isSuspended({}), false);
});

// A held run exits clean, which is indistinguishable from a run that found no
// work — unless it says which one it was.
test('a held run says why it did nothing, and how to resume', () => {
  assert.match(suspendedNotice(), new RegExp(SUSPEND_ALL_VAR));
  assert.match(suspendedNotice(), /resume/i);
});

// THE PRODUCER AND THE CONSUMER MUST AGREE. A knob stamped into no workflow is a
// knob nobody can turn; a knob read by no entry point is one that looks turnable
// and does nothing. Both halves are asserted here because the failure mode is
// silence on either side (#974).
test('every workflow stamps the hold, and every entry point reads it', () => {
  for (const wf of [
    '.github/workflows/claudinite-scheduler.yml',
    '.github/workflows/claudinite-executor.yml',
    'engine/scheduler/stubs/claudinite-tick.yml',
    'engine/scheduler/stubs/claudinite-executor.yml',
  ]) {
    assert.match(read(wf), new RegExp(`${SUSPEND_ALL_VAR}: \\$\\{\\{ vars\\.${SUSPEND_ALL_VAR} \\}\\}`), wf);
  }
  for (const entry of ['engine/scheduler/queue/tick.mjs', 'engine/scheduler/queue/executor.mjs']) {
    assert.match(read(entry), /isSuspended\(\)/, entry);
  }
});

// FIRST ACT means before the config load and before the first API call: a gate
// that ran after them would read the world it is meant not to touch.
test('the gate is the first thing either entry point does', () => {
  for (const entry of ['engine/scheduler/queue/tick.mjs', 'engine/scheduler/queue/executor.mjs']) {
    const main = read(entry).slice(read(entry).indexOf('async function main() {'));
    const gate = main.indexOf('isSuspended()');
    const firstRead = Math.min(
      ...[main.indexOf('loadConfig('), main.indexOf('makeGh(')].filter((n) => n > 0),
    );
    assert.ok(gate > 0 && gate < firstRead, `${entry}: the hold is checked after the run has already started reading`);
  }
});

// --- the bounds the heartbeat reframed (§15.15) --------------------------------

// F17, restated: what must hold is that a LIVE holder is never reclaimed. The old
// form of this — a run cap ≤ the leash — is what the heartbeat replaced.
test('a beating holder cannot be reclaimed: the interval is well inside the leash', () => {
  assert.ok(HEARTBEAT_MS * 3 < EXECUTING_LEASH_MS,
    `a holder must miss several beats before the leash reclaims it (${HEARTBEAT_MS}ms vs ${EXECUTING_LEASH_MS}ms)`);
});

// The cap's retirement is the whole point of the heartbeat, so a workflow that
// quietly reinstated one would undo it without anything failing.
test('no executor run is capped at the leash any more', () => {
  const executor = read('engine/scheduler/stubs/claudinite-executor.yml');
  const caps = [...executor.matchAll(/timeout-minutes:\s*(\d+)/g)].map((m) => Number(m[1]));
  assert.deepEqual(caps.length, 1, 'the executing job carries exactly one bound');
  assert.ok(caps[0] > EXECUTING_LEASH_MS / 60e3,
    'a cap at or under the leash is the retired F17 arithmetic, not a wedged-runner backstop');
});

// The drain must not sit in the tick's concurrency group (§15.16). It leaves by
// dispatching the executor workflow rather than being one — which is also why it
// needs no secrets and no work bound.
test('the tick workflow starts the drain rather than running it', () => {
  const tick = read('engine/scheduler/stubs/claudinite-tick.yml');
  assert.match(tick, /createWorkflowDispatch/, 'the drain dispatches');
  assert.doesNotMatch(tick, /queue\/executor\.mjs/, 'and never runs an executor inside the tick\'s group');
});

// THE HOLDER'S SIGN OF LIFE (tasks-dispatch DESIGN §6.5, §11, decision §15.15).
// A work step is the work: it may legitimately run for hours, and while it does
// the item goes dark and the executing leash cannot tell it from a dead runner.
// So the executor comments on its own item at a fixed interval, and the tick's
// reclaim measures silence from THAT rather than from a run-length cap.
//
// One mechanism, two things it buys: long work becomes legal (the run cap that
// held the leash arithmetic together retires), and the item's timeline stays live
// through work nobody can otherwise see.
//
// WHAT COUNTS AS ACTIVITY IS THE HOLDER'S OWN SIGNAL, never the issue's
// `updated_at` (#924). Any comment moves `updated_at` — including one written by
// an executor that LOST the claim race and let go — so a clock read off the issue
// defers the reclaim of an item nobody is working on. The struck claims a lost
// race leaves behind carry the episode marker, and are excluded here for exactly
// that reason.

import { CLAIM_MARKER, EPISODE_MARKER } from './work-item.mjs';

export const HEARTBEAT_MARKER = '<!-- claudinite-heartbeat -->';

// Comfortably inside the executing leash (60m), so a live holder is never
// reclaimed on a single missed beat: it takes four in a row.
export const HEARTBEAT_MS = 15 * 60e3;

export const heartbeatComment = ({ executor, at, minutes }) =>
  `${HEARTBEAT_MARKER}\nStill working: executor \`${executor}\`, ${minutes} minute(s) in, at ${at}.`;

// When the current holder last said anything — the newest live claim or heartbeat.
// A struck comment is not a signal: it says its author let the item go.
export function lastLivenessAt(comments = []) {
  const live = comments.filter((c) => {
    const body = c.body ?? '';
    if (body.includes(EPISODE_MARKER)) return false;
    return body.includes(CLAIM_MARKER) || body.includes(HEARTBEAT_MARKER);
  });
  const times = live.map((c) => new Date(c.created_at ?? 0).getTime()).filter((t) => t > 0);
  return times.length ? new Date(Math.max(...times)).toISOString() : null;
}

// Run `work` while beating. The beat is FAIL-SOFT — a comment that does not post
// must never sink a run that is otherwise fine — but never silent: a run whose
// heartbeat failed is one the leash may reclaim underneath it, and the log line is
// the only way to tell that from a run that simply finished quickly.
export async function withHeartbeat(work, { beat, intervalMs = HEARTBEAT_MS, log = () => {} }) {
  if (!beat || !(intervalMs > 0)) return work();
  const startedAt = Date.now();
  let beats = 0;
  const timer = setInterval(() => {
    const minutes = Math.round((Date.now() - startedAt) / 60e3);
    Promise.resolve()
      .then(() => beat(minutes))
      .then(() => { beats += 1; })
      .catch((e) => log(`! heartbeat ${beats + 1} did not post (${e?.message ?? e}) — the leash may reclaim this item mid-work`));
  }, intervalMs);
  // `unref` so a beat pending at exit cannot hold the process open past its work.
  timer.unref?.();
  try {
    return await work();
  } finally {
    clearInterval(timer);
    const minutes = Math.round((Date.now() - startedAt) / 60e3);
    if (beats) log(`- work step ran ${minutes} minute(s) and beat ${beats} time(s)`);
  }
}

// The holder's sign of life (DESIGN §15.15) and the reclaim clock it corrects
// (#924). Two things are pinned here that no single-call test could see: that the
// beat happens WHILE work is in flight, and that a comment written by an executor
// which let the item go does not read as that item being worked on.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  HEARTBEAT_MARKER, heartbeatComment, lastLivenessAt, withHeartbeat,
} from '../../../engine/scheduler/queue/heartbeat.mjs';
import { planTick } from '../../../engine/scheduler/queue/tick.mjs';
import { CLAIM_MARKER, EPISODE_MARKER } from '../../../engine/scheduler/queue/work-item.mjs';

const claim = (at, extra = '') => ({ created_at: at, body: `${CLAIM_MARKER}\nClaimed by executor \`E1\`.${extra}` });
const beat = (at) => ({ created_at: at, body: heartbeatComment({ executor: 'E1', at, minutes: 15 }) });

test('liveness is the newest live claim or heartbeat', () => {
  assert.equal(lastLivenessAt([claim('2026-08-20T04:00:00Z'), beat('2026-08-20T04:15:00Z')]),
    '2026-08-20T04:15:00.000Z');
  assert.equal(lastLivenessAt([]), null);
  // Ordinary prose on the item is not a sign that anyone is working on it.
  assert.equal(lastLivenessAt([{ created_at: '2026-08-20T05:00:00Z', body: 'just a comment' }]), null);
});

// #924, exactly: an executor that LOST the claim race strikes its own claim and
// walks away. That strike is a comment, so the issue's `updated_at` moves — and a
// clock read off the issue would defer the reclaim of an item nobody holds.
test('a struck claim is not a sign of life', () => {
  const struck = claim('2026-08-20T05:00:00Z', `\n\n${EPISODE_MARKER}\nThis claim is spent.`);
  assert.equal(lastLivenessAt([claim('2026-08-20T04:00:00Z'), struck]), '2026-08-20T04:00:00.000Z');
  assert.equal(lastLivenessAt([struck]), null);
});

// --- the reclaim reads it ------------------------------------------------------

const SCHEDULE = { dailyHour: 4, weeklyDay: 'Sun', monthlyDay: 1 };
const executing = (over = {}) => ({
  number: 1, title: '[claudinite-work] p/a', state: 'open', labels: ['task:executing'],
  body: 'packs/p/tasks/a/task.md\n', created_at: '2026-08-20T03:00:00Z',
  updated_at: '2026-08-20T03:00:00Z', ...over,
});
const reclaims = (item, now) => planTick({
  tasks: [], items: [item], now: new Date(now), schedule: SCHEDULE,
}).ops.filter((o) => o.kind === 'reclaim');

test('a beating holder is not reclaimed, however long its work runs', () => {
  const item = executing({ livenessAt: '2026-08-20T09:50:00Z', updated_at: '2026-08-20T09:50:00Z' });
  assert.deepEqual(reclaims(item, '2026-08-20T10:00:00Z'), [], 'six hours in and still alive');
});

test('a silent holder is reclaimed even though the item was commented on', () => {
  // The item was touched ten minutes ago — by somebody else — while its holder
  // has said nothing for two hours. The issue's clock says fresh; the holder's
  // says dead, and the holder's is the one that decides.
  const item = executing({ livenessAt: '2026-08-20T08:00:00Z', updated_at: '2026-08-20T09:50:00Z' });
  assert.equal(reclaims(item, '2026-08-20T10:00:00Z').length, 1);
});

test('an unreadable liveness falls back to the issue clock rather than reclaiming blind', () => {
  const fresh = executing({ livenessAt: null, updated_at: '2026-08-20T09:50:00Z' });
  assert.deepEqual(reclaims(fresh, '2026-08-20T10:00:00Z'), []);
  const stale = executing({ livenessAt: null, updated_at: '2026-08-20T08:00:00Z' });
  assert.equal(reclaims(stale, '2026-08-20T10:00:00Z').length, 1);
});

// --- the beat itself -----------------------------------------------------------

test('the beat runs while the work is in flight, and stops when it ends', async () => {
  const beats = [];
  let release;
  const work = new Promise((r) => { release = r; });
  const running = withHeartbeat(() => work, { intervalMs: 5, beat: (m) => beats.push(m) });
  await new Promise((r) => setTimeout(r, 40));
  assert.ok(beats.length >= 2, `beat while the work ran (got ${beats.length})`);
  release('done');
  assert.equal(await running, 'done');
  const after = beats.length;
  await new Promise((r) => setTimeout(r, 30));
  assert.equal(beats.length, after, 'and stopped the moment the work returned');
});

test('work that throws still stops the beat', async () => {
  const beats = [];
  await assert.rejects(
    withHeartbeat(async () => { throw new Error('boom'); }, { intervalMs: 5, beat: () => beats.push(1) }),
    /boom/);
  const after = beats.length;
  await new Promise((r) => setTimeout(r, 30));
  assert.equal(beats.length, after);
});

// A beat that cannot post must not sink a run that is otherwise fine — but it is
// never silent, because a run whose heartbeat failed is one the leash may reclaim
// underneath it, and nothing else would say so.
test('a failing beat is reported, not swallowed, and the work still returns', async () => {
  const lines = [];
  const res = await withHeartbeat(
    async () => { await new Promise((r) => setTimeout(r, 30)); return 'ok'; },
    { intervalMs: 5, beat: () => { throw new Error('403'); }, log: (l) => lines.push(l) });
  assert.equal(res, 'ok');
  assert.ok(lines.some((l) => l.startsWith('!') && l.includes('403')), lines.join('\n'));
});

test('the beat says who is working and how long they have been', () => {
  const body = heartbeatComment({ executor: 'E1', at: '2026-08-20T04:15:00Z', minutes: 15 });
  assert.ok(body.startsWith(HEARTBEAT_MARKER), 'machine-readable first');
  assert.match(body, /E1/);
  assert.match(body, /15 minute/);
});

// The terminal transition performed in code (#892) and the close-time release
// beside it (DESIGN §15.19). What these pin is the part a session used to do from
// prose: five ordered side effects, in order, exactly once — and the two ways it
// went wrong on live traffic (an item closed still wearing `task:agent`, an item
// closed with no execution record at all) failing loudly here instead.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  OUTCOMES, convergeItem, parseArgs, refusal, recordLine, convergeComment,
} from '../../../engine/scheduler/queue/converge-item.mjs';
import { releasedBy, isReleasable } from '../../../engine/scheduler/queue/readiness.mjs';

const item = (over = {}) => ({
  number: 7, title: '[claudinite-work] p/a', state: 'open', labels: ['task:agent'],
  body: 'packs/p/tasks/a/task.md\n', ...over,
});

// A fake repo driven through the same REST paths the shell calls.
function fakeRepo(issues) {
  const state = { issues, comments: [], calls: [] };
  const find = (n) => state.issues.find((i) => i.number === n);
  const gh = async (path, { method = 'GET', body } = {}) => {
    state.calls.push(`${method} ${path}`);
    let m;
    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\?/.exec(path))) {
      const page = Number(/[?&]page=(\d+)/.exec(path)?.[1] ?? 1);
      return { status: 200, json: page === 1 ? state.issues.filter((i) => i.state === 'open') : [] };
    }
    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)\/comments/.exec(path))) {
      state.comments.push({ issue: Number(m[1]), body: body.body });
      return { status: 201, json: {} };
    }
    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)\/labels\/(.+)$/.exec(path))) {
      const i = find(Number(m[1]));
      i.labels = i.labels.filter((l) => l !== decodeURIComponent(m[2]));
      return { status: 200, json: {} };
    }
    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)\/labels$/.exec(path))) {
      find(Number(m[1])).labels.push(...body.labels);
      return { status: 200, json: {} };
    }
    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)$/.exec(path))) {
      const i = find(Number(m[1]));
      if (method === 'PATCH') Object.assign(i, body);
      return { status: 200, json: i };
    }
    return { status: 404, json: null };
  };
  return { state, gh, find };
}

const api = await import('../../../engine/scheduler/github.mjs');
const run = (repo, plan, over = {}) => convergeItem(api, repo.gh, 'o/r', plan, { log: () => {}, ...over });

// --- the argument surface ------------------------------------------------------

test('the command refuses a plan it cannot perform rather than guessing', () => {
  assert.match(parseArgs(['--outcome', 'done', '--summary', 'x']).error, /--issue/);
  assert.match(parseArgs(['--issue', '7', '--summary', 'x']).error, /--outcome/);
  assert.match(parseArgs(['--issue', '7', '--outcome', 'nope', '--summary', 'x']).error, /--outcome/);
  assert.match(parseArgs(['--issue', '7', '--outcome', 'done', '--summary', '   ']).error, /--summary/);
  // An approval park nobody can act on is not a park.
  assert.match(parseArgs(['--issue', '7', '--outcome', 'approval', '--summary', 'x']).error, /--pr/);
  assert.deepEqual(parseArgs(['--issue', '7', '--outcome', 'done', '--summary', 'did it']),
    { issue: 7, outcome: 'done', summary: 'did it', pr: null });
});

// --- who may converge ----------------------------------------------------------

test('an item this session does not hold is refused, not converged', () => {
  assert.match(refusal(null, 7), /could not be read/);
  assert.match(refusal(item({ title: 'just an issue' }), 7), /not a Claudinite work item/);
  assert.match(refusal(item({ state: 'closed' }), 7), /already closed/);
  assert.match(refusal(item({ labels: ['task:executing'] }), 7), /task:agent/);
  assert.equal(refusal(item(), 7), null);
});

test('a refusal writes nothing at all', async () => {
  const repo = fakeRepo([item({ labels: ['task:executing'] })]);
  const res = await run(repo, { issue: 7, outcome: 'done', summary: 'did it' });
  assert.equal(res.ok, false);
  assert.deepEqual(repo.state.comments, []);
  assert.deepEqual(repo.find(7).labels, ['task:executing']);
  assert.equal(repo.find(7).state, 'open');
});

// --- the close: all five side effects, and the record ---------------------------

test('a done outcome closes the item with the label swapped and the record on it', async () => {
  const repo = fakeRepo([item()]);
  const res = await run(repo, { issue: 7, outcome: 'done', summary: 'ran the thing' });
  assert.equal(res.ok, true);
  const issue = repo.find(7);
  assert.equal(issue.state, 'closed');
  assert.equal(issue.state_reason, 'completed');
  assert.ok(issue.labels.includes('task:done'));
  // The failure that reached live traffic: a closed item still reading as live.
  assert.equal(issue.labels.includes('task:agent'), false, 'a closed item must not wear task:agent');
  // …and the other one: closed with no record at all.
  assert.match(repo.state.comments[0].body, /ran the thing/);
  assert.match(repo.state.comments[0].body, /claudinite-task-exec v1 p\/a \[#7\] success/);
});

test('the record is printed as well as commented — the census reads the transcript', async () => {
  const repo = fakeRepo([item()]);
  const printed = [];
  await run(repo, { issue: 7, outcome: 'done', summary: 'x' }, { log: (l) => printed.push(l) });
  assert.deepEqual(printed.filter((l) => l.startsWith('claudinite-task-exec')),
    ['claudinite-task-exec v1 p/a [#7] success']);
});

// An approval park is a run that SUCCEEDED and left a PR. The record vocabulary
// has no word for that, and absence is the honest answer — never a `failed` that
// would read as a broken run in the census.
test('a park that is not a failure carries no record', () => {
  assert.equal(recordLine(item(), OUTCOMES.approval.record), null);
  assert.equal(recordLine(item(), OUTCOMES.failure.record), 'claudinite-task-exec v1 p/a [#7] failed');
  assert.doesNotMatch(convergeComment(item(), { summary: 's', pr: 9, record: null }), /claudinite-task-exec/);
});

test('a park leaves the item open wearing both labels', async () => {
  const repo = fakeRepo([item()]);
  await run(repo, { issue: 7, outcome: 'failure', summary: 'it broke' });
  const issue = repo.find(7);
  assert.equal(issue.state, 'open');
  assert.deepEqual(issue.labels.sort(), ['needs-human', 'task:needs-human-failure']);
});

// --- the request write-back ----------------------------------------------------

test('an approval park hands its request issue to the reviewer', async () => {
  const repo = fakeRepo([
    item({ body: 'packs/p/tasks/a/task.md\n\nRequest: #42\n' }),
    { number: 42, title: 'do a thing', state: 'open', labels: ['claude-queued'] },
  ]);
  await run(repo, { issue: 7, outcome: 'approval', summary: 'opened it', pr: 9 });
  assert.deepEqual(repo.find(42).labels, ['claude-in-review']);
  assert.match(repo.state.comments.find((c) => c.issue === 42).body, /#9/);
});

// A failure writes NOTHING to the request and leaves `claude-queued` standing:
// re-arming work that writes code is a person's decision, and that standing label
// is what stops the next tick queueing a second run of the same request.
test('a failure park leaves the request armed and says nothing to it', async () => {
  const repo = fakeRepo([
    item({ body: 'packs/p/tasks/a/task.md\n\nRequest: #42\n' }),
    { number: 42, title: 'do a thing', state: 'open', labels: ['claude-queued'] },
  ]);
  await run(repo, { issue: 7, outcome: 'failure', summary: 'it broke' });
  assert.deepEqual(repo.find(42).labels, ['claude-queued']);
  assert.equal(repo.state.comments.some((c) => c.issue === 42), false);
});

// --- the close-time release (DESIGN §15.19) ------------------------------------

const blocked = (number, blockedBy, over = {}) => ({
  number, title: `[claudinite-work] p/b${number}`, state: 'open', labels: ['task:blocked'],
  body: `packs/p/tasks/b/task.md\n\nBlocked-by: ${blockedBy.map((n) => `#${n}`).join(', ')}\n`, ...over,
});

test('closing an item readies what it was the last blocker of', async () => {
  const repo = fakeRepo([item(), blocked(8, [7])]);
  const res = await run(repo, { issue: 7, outcome: 'done', summary: 'x' });
  assert.deepEqual(res.freed, [8]);
  assert.deepEqual(repo.find(8).labels, ['task:ready']);
});

test('an item still waiting on a second blocker is left alone', async () => {
  const repo = fakeRepo([
    item(), blocked(8, [7, 9]),
    { number: 9, title: 'other', state: 'open', labels: [] },
  ]);
  const res = await run(repo, { issue: 7, outcome: 'done', summary: 'x' });
  assert.deepEqual(res.freed, []);
  assert.deepEqual(repo.find(8).labels, ['task:blocked']);
